css:
.stickysim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2733;
    background: linear-gradient(160deg, #f4f1ea 0%, #eae4d6 100%);
    border-radius: 18px;
}

.stickysim-container * {
    box-sizing: border-box;
}

.stickysim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #14233d 0%, #1d3a5f 55%, #2b5179 100%);
    color: #f6f2e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 35, 61, 0.32);
}

.stickysim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.stickysim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7c878;
    background: rgba(231, 200, 120, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.stickysim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dde5ef;
}

.stickysim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2b3f5c;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.stickysim-period-counter #currentDay,
.stickysim-period-counter #maxPeriods {
    font-weight: 800;
    color: #14233d;
}

.stickysim-round-name {
    background: #dfe7f1;
    color: #14233d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.stickysim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a12;
    background: #f6e7c4;
    padding: 4px 12px;
    border-radius: 999px;
}

.stickysim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.stickysim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e3dcc9;
    box-shadow: 0 4px 14px rgba(20, 35, 61, 0.06);
    border-top: 4px solid #2b5179;
}

.stickysim-card-useful { border-top-color: #1d6f4f; }
.stickysim-card-transfer { border-top-color: #2b5179; }
.stickysim-card-satis { border-top-color: #b08a2a; }
.stickysim-card-cost { border-top-color: #7a4ba0; }

.stickysim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7587;
}

.stickysim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14233d;
}

.stickysim-card-useful .stickysim-value { color: #1d6f4f; }
.stickysim-card-transfer .stickysim-value { color: #2b5179; }
.stickysim-card-satis .stickysim-value { color: #b08a2a; }
.stickysim-card-cost .stickysim-value { color: #7a4ba0; }

.stickysim-sublabel {
    font-size: 0.74rem;
    color: #7c8696;
    line-height: 1.35;
}

.stickysim-useful-target .stickysim-value { color: #1d6f4f; }
.stickysim-useful-low .stickysim-value { color: #c0392b; }
.stickysim-transfer-target .stickysim-value { color: #1d6f4f; }
.stickysim-transfer-low .stickysim-value { color: #c0392b; }

.stickysim-cost-over .stickysim-value { color: #c0392b; }
.stickysim-cost-over { border-top-color: #c0392b; }

.stickysim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14233d;
    color: #f0ece0;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.stickysim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7c878;
}

.stickysim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b08a2a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 35, 61, 0.05);
}

.stickysim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.stickysim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14233d;
    margin-bottom: 6px;
}

.stickysim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34404f;
}

.stickysim-briefing-text strong { color: #1d6f4f; }
.stickysim-briefing-text em { color: #8a5a12; font-style: italic; }

.stickysim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3dcc9;
    box-shadow: 0 4px 14px rgba(20, 35, 61, 0.06);
}

.stickysim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14233d;
    border-bottom: 2px solid #eee7d6;
    padding-bottom: 8px;
}

.stickysim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #243551;
    margin: 14px 0 6px;
}

.stickysim-container select,
.stickysim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cfc6b0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf9f3;
    color: #1f2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.stickysim-container select:focus,
.stickysim-container input[type="number"]:focus {
    outline: none;
    border-color: #2b5179;
    box-shadow: 0 0 0 3px rgba(43, 81, 121, 0.15);
}

.stickysim-container select option {
    background-color: #ffffff;
    color: #1f2733;
}

.stickysim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b08a2a;
}

.stickysim-range-readout,
.stickysim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2b5179;
    margin-top: 4px;
}

.stickysim-range-readout span:last-child,
.stickysim-alloc-readout span:nth-child(2) {
    color: #1d6f4f;
    font-weight: 800;
}

.stickysim-hint {
    font-size: 0.8rem;
    color: #7c8696;
    margin-top: 4px;
    line-height: 1.4;
}

.stickysim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.stickysim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f8f5ec;
    border: 1px solid #e8e1ce;
    border-radius: 9px;
    padding: 8px 12px;
}

.stickysim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #243551;
}

.stickysim-alloc-row input[type="number"] {
    width: 100px;
    flex: 0 0 100px;
}

.stickysim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.stickysim-container .btn-primary {
    background: linear-gradient(135deg, #1d6f4f 0%, #2b5179 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(29, 111, 79, 0.28);
}

.stickysim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.stickysim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cfc6b0;
    color: #6a7587;
}

.stickysim-coach {
    background: #14233d;
    color: #eef0f5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 35, 61, 0.24);
}

.stickysim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7c878;
    margin-bottom: 8px;
}

.stickysim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.stickysim-coach-body strong { color: #f0cf86; }
.stickysim-coach-body em { color: #f0b89a; font-style: italic; }

.stickysim-history,
.stickysim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3dcc9;
    box-shadow: 0 4px 14px rgba(20, 35, 61, 0.06);
}

.stickysim-history h3,
.stickysim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14233d;
}

.stickysim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #243551;
}

.stickysim-container table#usfHistoryTable th {
    background: #f1ecdd;
    color: #14233d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e3dcc9;
}

.stickysim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece0;
}

.stickysim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f1;
}

.stickysim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .stickysim-container {
        padding: 14px;
    }
    .stickysim-header h1 {
        font-size: 1.7rem;
    }
    .stickysim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .stickysim-value {
        font-size: 2rem;
    }
    .stickysim-clock {
        margin-left: 0;
    }
    .stickysim-period-counter {
        font-size: 0.88rem;
    }
    .stickysim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .stickysim-alloc-row {
        flex-wrap: wrap;
    }
    .stickysim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .stickysim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (dark-on-light for the framework's white modal) ===== */
.stickysim-cm { text-align: center; color: #23303a; padding: 8px 4px 4px; }
.stickysim-cm-title { font-size: 1.05rem; font-weight: 700; color: #2f5d7c; margin-bottom: 10px; }
.stickysim-cm-scorewrap { margin: 4px 0 6px; }
.stickysim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #2f5d7c; }
.stickysim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6a7587; }
.stickysim-cm-scorelabel { font-size: .78rem; text-transform: uppercase; letter-spacing: .05em; color: #6a7587; }
.stickysim-cm-grade { font-size: 1.3rem; font-weight: 700; color: #23303a; margin: 6px 0; }
.stickysim-cm-badges { margin: 8px 0 12px; }
.stickysim-cm-badge { display: inline-block; padding: 5px 12px; border-radius: 999px; font-size: .82rem; font-weight: 700; }
.stickysim-cm-badge-ok { background: #d7ecdd; color: #1e6b40; border: 1px solid #2f9e5f; }
.stickysim-cm-badge-fail { background: #f7d9d5; color: #8f2418; border: 1px solid #c0392b; }
.stickysim-cm-badge-warn { background: #fdf0d6; color: #8a5a12; border: 1px solid #d59a2c; }
.stickysim-cm-kpis { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; margin: 10px 0; }
.stickysim-cm-kpi { background: #eef2f6; border: 1px solid #dbe2ea; border-radius: 10px; padding: 10px 14px; min-width: 92px; }
.stickysim-cm-kpi-n { font-size: 1.5rem; font-weight: 800; color: #2f5d7c; }
.stickysim-cm-kpi-l { font-size: .72rem; text-transform: uppercase; letter-spacing: .03em; color: #6a7587; }
.stickysim-cm-insights { text-align: left; margin: 12px auto 2px; max-width: 560px; background: #f4f7fa; border: 1px solid #e2e8ef; border-radius: 10px; padding: 10px 14px; }
.stickysim-cm-insights-h { font-weight: 700; color: #2f5d7c; margin-bottom: 6px; font-size: .9rem; }
.stickysim-cm-insights ul { margin: 0; padding-left: 18px; }
.stickysim-cm-insights li { color: #32404d; font-size: .88rem; margin-bottom: 4px; }

