(function() {
    'use strict';

    class StickyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Training That Sticks`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Banque Aurore, EUR).
            this.START_USEFUL = 24;        // pilot 2.4/5 -> x10
            this.START_TRANSFER = 11;      // pilot 11% observed behaviour change
            this.START_SATIS = 39;         // pilot 3.9/5 enjoyment
            this.TARGET_USEFUL = 70;       // design-for-usefulness target
            this.TARGET_TRANSFER = 60;     // demonstrable conversion target
            this.COST_CAP = 792;           // EUR per learner cap (1.9M / 2400)
            this.LEARNERS = 2400;          // rollout population
            this.BUDGET_CAP = 1900000;     // EUR 1.9M

            this.TRUE_CAUSE = `usefulness`;
            this.TRUE_METRIC = `transfer`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    useful: this.START_USEFUL,
                    transfer: this.START_TRANSFER,
                    satis: this.START_SATIS,
                    costPerLearner: 0,
                    overCap: false,
                    enjoymentTrap: false,
                    usefulHistory: [this.START_USEFUL],
                    transferHistory: [this.START_TRANSFER],
                    satisHistory: [this.START_SATIS],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    cause: `usefulness`,
                    metric: `transfer`,
                    honesty: 60,
                    content: `tailored`,
                    segment: `segmented`,
                    practice: 80,
                    trainer: `coaches`,
                    contentSpend: 150,
                    trainerSpend: 250,
                    reinforceSpend: 180,
                    eval: `fourlevel`,
                    recovery: `diagnose`,
                    pitch: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const cause = document.getElementById(`causeInput`);
                const metric = document.getElementById(`metricInput`);
                const hon = document.getElementById(`honestyInput`);
                if (cause) decisions.cause = cause.value;
                if (metric) decisions.metric = metric.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const content = document.getElementById(`contentInput`);
                const segment = document.getElementById(`segmentInput`);
                const practice = document.getElementById(`practiceInput`);
                if (content) decisions.content = content.value;
                if (segment) decisions.segment = segment.value;
                if (practice) decisions.practice = parseFloat(practice.value);
                if (!Number.isFinite(decisions.practice) || decisions.practice < 0 || decisions.practice > 160) {
                    warn(`warn_practice_range`); return false;
                }
            } else if (round === 3) {
                const trainer = document.getElementById(`trainerInput`);
                const cs = document.getElementById(`contentSpendInput`);
                const ts = document.getElementById(`trainerSpendInput`);
                const rs = document.getElementById(`reinforceSpendInput`);
                if (trainer) decisions.trainer = trainer.value;
                if (cs) decisions.contentSpend = parseFloat(cs.value);
                if (ts) decisions.trainerSpend = parseFloat(ts.value);
                if (rs) decisions.reinforceSpend = parseFloat(rs.value);
                const parts = [decisions.contentSpend, decisions.trainerSpend, decisions.reinforceSpend];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
            } else if (round === 4) {
                const ev = document.getElementById(`evalInput`);
                const rec = document.getElementById(`recoveryInput`);
                const pitch = document.getElementById(`pitchInput`);
                if (ev) decisions.eval = ev.value;
                if (rec) decisions.recovery = rec.value;
                if (pitch) decisions.pitch = parseInt(pitch.value, 10);
                if (!Number.isFinite(decisions.pitch) || decisions.pitch < 0 || decisions.pitch > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let usefulDelta = 0, transferDelta = 0, satisDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: separate enjoyment from the drivers research links to use.
                if (d.cause === this.TRUE_CAUSE) {
                    usefulDelta += 10; transferDelta += 4; coachKey = `coach_r1_cause_right`;
                } else if (d.cause === `enjoyment`) {
                    usefulDelta -= 6; satisDelta += 6; transferDelta -= 3; coachKey = `coach_r1_enjoyment`;
                } else if (d.cause === `completion`) {
                    usefulDelta -= 4; transferDelta -= 4; coachKey = `coach_r1_completion`;
                } else {
                    usefulDelta -= 6; transferDelta -= 5; coachKey = `coach_r1_staff`;
                }

                // The metric leadership should have watched.
                if (d.metric === this.TRUE_METRIC) {
                    usefulDelta += 6; transferDelta += 5;
                    if (d.cause === this.TRUE_CAUSE) coachKey = `coach_r1_diag_sharp`;
                } else if (d.metric === `enjoyment`) {
                    usefulDelta -= 5; satisDelta += 4; coachKey = `coach_r1_metric_enjoy`;
                } else {
                    usefulDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r1_metric_wrong` : coachKey;
                }

                // Honesty: design for transfer, not attendance.
                if (d.honesty >= 60) { transferDelta += 4; usefulDelta += 2; }
                else if (d.honesty <= 25) { transferDelta -= 5; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.cause === this.TRUE_CAUSE && d.metric === this.TRUE_METRIC) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Content relevance is the usefulness lever — not a place to economize blindly.
                switch (d.content) {
                    case `tailored`: spend += 320; usefulDelta += 18; transferDelta += 6; coachKey = `coach_r2_tailored`; break;
                    case `hybrid`: spend += 210; usefulDelta += 8; transferDelta += 3; coachKey = `coach_r2_hybrid`; break;
                    case `generic`: spend += 180; usefulDelta -= 8; transferDelta -= 4; satisDelta += 2; coachKey = `coach_r2_generic`; break;
                }

                // Segmentation by branch type and seniority lifts perceived relevance.
                if (d.segment === `segmented`) {
                    spend += 60; usefulDelta += 6; transferDelta += 3;
                    if (d.content === `tailored`) coachKey = `coach_r2_relevant`;
                } else {
                    usefulDelta -= 2;
                }

                // Practice on the bank's real products — strongest usefulness lever.
                spend += d.practice;
                if (d.practice >= 80) { usefulDelta += 10; transferDelta += 6; }
                else if (d.practice >= 40) { usefulDelta += 5; transferDelta += 3; }
                else { usefulDelta -= 4; transferDelta -= 3; coachKey = `coach_r2_nopractice`; }

                summaryKey = (d.content === `tailored` && d.practice >= 80) ? `sum_r2_good` : (d.content === `generic` ? `sum_r2_generic` : `sum_r2_weak`);
            } else if (round === 3) {
                // Trainer/format and manager reinforcement: the two levers most tightly linked to transfer.
                switch (d.trainer) {
                    case `coaches`: usefulDelta += 8; transferDelta += 12; satisDelta += 2; coachKey = `coach_r3_coaches`; break;
                    case `blended`: usefulDelta += 6; transferDelta += 9; satisDelta += 3; coachKey = `coach_r3_blended`; break;
                    case `external`: usefulDelta += 6; transferDelta += 6; satisDelta += 6; coachKey = `coach_r3_external`; break;
                    case `elearning`: usefulDelta -= 4; transferDelta -= 6; satisDelta += 4; coachKey = `coach_r3_elearning`; break;
                }

                const cs = d.contentSpend, ts = d.trainerSpend, rs = d.reinforceSpend;
                spend += cs + ts + rs;

                // Manager reinforcement: under-funding it repeats the pilot's 9% follow-up failure.
                if (rs >= 150) { transferDelta += 14; usefulDelta += 3; if (d.trainer === `coaches` || d.trainer === `blended`) coachKey = `coach_r3_reinforced`; }
                else if (rs >= 80) { transferDelta += 7; }
                else if (rs >= 30) { transferDelta += 2; coachKey = `coach_r3_thinreinforce`; }
                else { transferDelta -= 10; coachKey = `coach_r3_noreinforce`; }

                // Prestige over-spend: external trainers + heavy trainer spend blows the cap.
                if (d.trainer === `external` && ts >= 400) { coachKey = `coach_r3_prestige`; }

                summaryKey = (rs >= 150 && (d.trainer === `coaches` || d.trainer === `blended`)) ? `sum_r3_good`
                    : (rs < 30 ? `sum_r3_noreinforce` : `sum_r3_weak`);
            } else if (round === 4) {
                // Evaluation must climb past Level 1 to behaviour and results.
                switch (d.eval) {
                    case `fourlevel`: usefulDelta += 4; transferDelta += 8; coachKey = `coach_r4_fourlevel`; break;
                    case `behaviour`: transferDelta += 5; coachKey = `coach_r4_behaviour`; break;
                    case `learning`: transferDelta += 1; coachKey = `coach_r4_learning`; break;
                    case `happysheet`: transferDelta -= 6; satisDelta += 3; coachKey = `coach_r4_happysheet`; break;
                }

                // Recovery: diagnose the driver rather than re-running the course.
                switch (d.recovery) {
                    case `diagnose`: usefulDelta += 6; transferDelta += 12; coachKey = (d.eval === `fourlevel`) ? `coach_r4_diagnose` : coachKey; break;
                    case `reinforce`: transferDelta += 9; usefulDelta += 2; coachKey = `coach_r4_recover_reinforce`; break;
                    case `rerun`: transferDelta -= 6; satisDelta += 2; coachKey = `coach_r4_rerun`; break;
                    case `enjoyment`: transferDelta -= 4; satisDelta += 8; coachKey = `coach_r4_recover_enjoy`; break;
                }

                // Conviction defending design-for-transfer over the cheap e-learning option.
                transferDelta += Math.round((d.pitch - 60) / 8);

                summaryKey = (d.eval === `fourlevel` && (d.recovery === `diagnose` || d.recovery === `reinforce`)) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Cost accounting (per learner, EUR).
            ds.costPerLearner = Math.round(ds.costPerLearner + spend);

            // Over-cap penalty: when you run past EUR 792/learner the money runs out, so the
            // rollout gets squeezed — transfer suffers (this is what kills the prestige-trainer plan).
            const over = ds.costPerLearner - this.COST_CAP;
            if (over > 0) {
                ds.overCap = true;
                const penalty = Math.min(18, Math.ceil(over / 40));
                transferDelta -= penalty;
                if (round >= 3 && over > 120) coachKey = `coach_overcap`;
            }

            ds.useful = Math.max(0, Math.min(100, ds.useful + usefulDelta));
            ds.transfer = Math.max(0, Math.min(100, ds.transfer + transferDelta));
            ds.satis = Math.max(0, Math.min(100, ds.satis + satisDelta));

            // The enjoyment trap: satisfaction high while transfer stays stuck.
            if (ds.satis >= 55 && ds.transfer < 35 && round >= 2) ds.enjoymentTrap = true;

            ds.usefulHistory.push(Math.round(ds.useful));
            ds.transferHistory.push(Math.round(ds.transfer));
            ds.satisHistory.push(Math.round(ds.satis));

            // v1.1.0 FIX — persist the composite where the grading/reporting layer reads it
            // (express_resolveDomainScore -> domainState.performance.overallScore), every period.
            const overallScore = this._composite(ds);
            ds.performance = { overallScore: overallScore };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                useful: Math.round(ds.useful),
                usefulDelta: Math.round(usefulDelta),
                transfer: Math.round(ds.transfer),
                transferDelta: Math.round(transferDelta),
                satis: Math.round(ds.satis),
                satisDelta: Math.round(satisDelta),
                costPerLearner: ds.costPerLearner,
                overCap: ds.overCap,
                enjoymentTrap: ds.enjoymentTrap,
                score: overallScore,
                overallScore: overallScore,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtTotal(costPerLearner) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const total = Math.round(costPerLearner * this.LEARNERS);
            const millions = total / 1000000;
            if (lang === `es`) {
                const m = millions.toFixed(2).replace(`.`, `,`);
                return `${m} M€ / 1,9 M€`;
            }
            return `€${millions.toFixed(2)}M / €1.9M`;
        }

        _fmtPerLearner(v) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const n = Math.round(Number(v));
            return lang === `es` ? `${n} €` : `€${n}`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`usefulDisplay`, `domainState.useful`, (v) => {
                const card = document.querySelector(`.stickysim-card-useful`);
                if (card) {
                    card.classList.toggle(`stickysim-useful-target`, Number(v) >= this.TARGET_USEFUL);
                    card.classList.toggle(`stickysim-useful-low`, Number(v) < 40);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`transferDisplay`, `domainState.transfer`, (v) => {
                const card = document.querySelector(`.stickysim-card-transfer`);
                if (card) {
                    card.classList.toggle(`stickysim-transfer-target`, Number(v) >= this.TARGET_TRANSFER);
                    card.classList.toggle(`stickysim-transfer-low`, Number(v) < 30);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`satisDisplay`, `domainState.satis`, (v) => Math.round(Number(v)));
            uiManager.bind(`costDisplay`, `domainState.costPerLearner`, (v) => {
                const card = document.querySelector(`.stickysim-card-cost`);
                if (card) card.classList.toggle(`stickysim-cost-over`, Number(v) > this.COST_CAP);
                return this._fmtPerLearner(v);
            });
            uiManager.bind(`budgetDisplay`, `domainState.costPerLearner`, (v) => this._fmtTotal(Number(v)));

            const self = this;

            // Honesty slider readout.
            const hon = document.getElementById(`honestyInput`);
            const honReadout = document.getElementById(`honestyReadout`);
            if (hon && honReadout) {
                honReadout.textContent = hon.value;
                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            // Round-3 allocation live total (per learner).
            const allocIds = [`contentSpendInput`, `trainerSpendInput`, `reinforceSpendInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = self._fmtPerLearner(total);
                const bar = document.querySelector(`.stickysim-alloc-readout`);
                if (bar) bar.style.color = (total > self.COST_CAP) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        // v1.1.0 — composite 0-100 the reporting layer reads. Formula identical to
        // getPerformanceSummary; clamped to [0,100] (the raw formula can go negative when
        // over budget, and express_resolveDomainScore expects a 0-100 value).
        _composite(ds) {
            const useful = Math.round(ds.useful);
            const transfer = Math.round(ds.transfer);
            const satis = Math.round(ds.satis);
            const onBudget = Math.round(ds.costPerLearner) <= this.COST_CAP;
            return Math.max(0, Math.min(100, Math.round(useful * 0.35 + transfer * 0.45 + satis * 0.20 - (onBudget ? 0 : 12))));
        }

        // v1.1.0 — safe i18n lookup with English fallback (chart/legend chrome).
        _cl(key, fallback) {
            try {
                const s = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
                return (s && s !== key) ? s : fallback;
            } catch (e) { return fallback; }
        }

        getChartConfig() {
            return {
