        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.usefulHistory.map((_, i) => (i === 0 ? `Pilot` : `R` + i));
            return {
                stickyChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.usefulHistory },
                        { data: ds.transferHistory },
                        { data: ds.satisHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const useful = Math.round(ds.useful);
            const transfer = Math.round(ds.transfer);
            const satis = Math.round(ds.satis);
            const costPerLearner = Math.round(ds.costPerLearner);

            const hitUseful = useful >= this.TARGET_USEFUL;
            const hitTransfer = transfer >= this.TARGET_TRANSFER;
            const onBudget = costPerLearner <= this.COST_CAP;
            const trap = ds.enjoymentTrap || (satis >= 55 && transfer < 35);
            const composite = this._composite(ds);

            let gradeKey = `grade_repeated`;
            if (hitUseful && hitTransfer && onBudget && composite >= 70) gradeKey = `grade_stuck`;
            else if (hitUseful && hitTransfer) gradeKey = (onBudget ? `grade_achieved` : `grade_overbudget`);
            else if (trap) gradeKey = `grade_trap`;
            else if (transfer >= this.START_TRANSFER + 25) gradeKey = `grade_short`;
            const performance = window.mySimulation.t(gradeKey);

            const insights = [];
            if (hitUseful && hitTransfer && onBudget) insights.push(window.mySimulation.t(`insight_stuck`));
            else if (hitUseful && hitTransfer && !onBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            else if (trap) insights.push(window.mySimulation.t(`insight_trap`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (transfer < 35) insights.push(window.mySimulation.t(`insight_lowtransfer`));
            if (useful < 45) insights.push(window.mySimulation.t(`insight_lowuseful`));
            if (!onBudget) insights.push(window.mySimulation.t(`insight_cost`));
            if (hitUseful && hitTransfer && transfer >= 70) insights.push(window.mySimulation.t(`insight_excellent`));

            return {
                useful: useful,
                transfer: transfer,
                satis: satis,
                costPerLearner: costPerLearner,
                onBudget: onBudget,
                trap: trap,
                composite: composite,
                performance: performance,
                gradeKey: gradeKey,
                passed: (hitUseful && hitTransfer && onBudget),
                insights: insights
            };
        }

        // v1.1.0 FIX — real completion modal (score / localized grade / MET or distinct-failure
        // badge / KPI strip / insights). Replaces the framework's generic fallback.
        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;
            const s = summary || {};
            const score = Number.isFinite(s.composite) ? s.composite : 0;
            const grade = s.performance || t(s.gradeKey || `grade_repeated`);
            const passed = !!s.passed;
            const k = (v) => Math.round(v != null ? v : 0);
            const cost = this._fmtPerLearner(s.costPerLearner != null ? s.costPerLearner : 0);
            let badge;
            if (passed) {
                badge = `<span class="stickysim-cm-badge stickysim-cm-badge-ok">\u2713 ` + t(`cm_met`) + `</span>`;
            } else if (s.trap) {
                badge = `<span class="stickysim-cm-badge stickysim-cm-badge-fail">\u2715 ` + t(`cm_fail_trap`) + `</span>`;
            } else if (s.onBudget === false) {
                badge = `<span class="stickysim-cm-badge stickysim-cm-badge-fail">\u2715 ` + t(`cm_fail_cost`) + `</span>`;
            } else {
                badge = `<span class="stickysim-cm-badge stickysim-cm-badge-warn">\u2022 ` + t(`cm_missed`) + `</span>`;
            }
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightHtml = insights.length
                ? `<div class="stickysim-cm-insights"><div class="stickysim-cm-insights-h">` + t(`cm_insights`) + `</div><ul>` + insights.map((x) => `<li>` + x + `</li>`).join(``) + `</ul></div>`
                : ``;
            return `
                <div class="stickysim-cm">
                    <div class="stickysim-cm-title">` + t(`cm_title`) + `</div>
                    <div class="stickysim-cm-scorewrap">
                        <div class="stickysim-cm-score">` + score + `<span class="stickysim-cm-score-max">/100</span></div>
                        <div class="stickysim-cm-scorelabel">` + t(`cm_score_of`) + `</div>
                    </div>
                    <div class="stickysim-cm-grade">` + grade + `</div>
                    <div class="stickysim-cm-badges">` + badge + `</div>
                    <div class="stickysim-cm-kpis">
                        <div class="stickysim-cm-kpi"><div class="stickysim-cm-kpi-n">` + k(s.useful) + `</div><div class="stickysim-cm-kpi-l">` + t(`cm_useful`) + `</div></div>
                        <div class="stickysim-cm-kpi"><div class="stickysim-cm-kpi-n">` + k(s.transfer) + `%</div><div class="stickysim-cm-kpi-l">` + t(`cm_transfer`) + `</div></div>
                        <div class="stickysim-cm-kpi"><div class="stickysim-cm-kpi-n">` + k(s.satis) + `</div><div class="stickysim-cm-kpi-l">` + t(`cm_satis`) + `</div></div>
                        <div class="stickysim-cm-kpi"><div class="stickysim-cm-kpi-n">` + cost + `</div><div class="stickysim-cm-kpi-l">` + t(`cm_cost`) + `</div></div>
                    </div>
                    ` + insightHtml + `
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.enjoymentTrap) return window.mySimulation.t(`hint_trap`);
            if (ds.overCap && state.currentPeriod >= 3) return window.mySimulation.t(`hint_cost`);
            if (ds.transfer < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_transfer`);
            if (ds.useful < 35) return window.mySimulation.t(`hint_useful`);
            if (ds.useful >= this.TARGET_USEFUL && ds.transfer >= this.TARGET_TRANSFER) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
