                { key: `results.useful`, label: `Usefulness`, i18nKey: `col_useful`, formatter: (v) => Math.round(v) },
                { key: `results.transfer`, label: `Transfer`, i18nKey: `col_transfer`, formatter: (v) => Math.round(v) + `%` },
